    "summaryAr": "ملف للسياجات والشجيرات الورقية؛ لا يعني تجانس احتياجات الأنواع. اضبط الشمس والري حسب النبات: البقس قد يستفيد من ظل بعد الظهر، والفوتينيا تزهر وتلون نموها أفضل في ضوء أقوى. اترك تباعدًا كافيًا لتقليل الرطوبة والمرض.",
    "titleAr": "الشجيرات دائمة الخضرة والسياجات",
    "waterMatureAr": "بعد الاستقرار افحص التربة بعد فترات الجفاف، واسقِ فقط عندما تجف منطقة الجذور؛ الأنواع المتحملة قد لا تحتاج إلا في موجة جفاف طويلة، بينما الأصص والفوتينيا المحمية من المطر تحتاج متابعة أكثر. لا تعتمد عدد أيام ثابتًا، ولا تجعل قاعدة الشجيرات رطبة باستمرار.",
    "waterSeedlingAr": "اسقِ مباشرة بعد الزراعة. في أول أسبوعين افحص يوميًا قرب كرة الجذور واسقِ إذا جفت، ثم أسبوعيًا خلال السنة الأولى عند جفاف التربة على عمق 5–8 سم. بلل منطقة الجذور ببطء دون تبليل الأوراق؛ الرمل والأصص والحر والريح تزيد الحاجة، والطين والمطر يقللانها.",
    "waterYoungAr": "بعمر 1–3 سنوات افحص أسبوعيًا في الحر، واسقِ بعمق عندما تجف التربة تحت السطح؛ وسّع الري إلى محيط الجذور مع نموها. السياج المزروع بكثافة أو في تربة رملية قد يجف أسرع؛ التربة الثقيلة تحتاج فواصل أطول لتجنب الاختناق."
