    "matchNotesAr": "يطابق Bougainvillea spp والأصناف المقزمة/المشكلة، Lantana camara وL. montevidensis وLeucophyllum frutescens وPlumbago auriculata؛ الأنواع المذكورة ليست كلها متطابقة. اللانتانا قد تنتشر وتحتاج احتواءً محليًا، والاسم التجاري للأصناف لا يحدد تحملها بدقة.",
