        "treatmentAr": "اغسل المستعمرات بالماء أو أزل الأطراف المصابة، وكرر الفحص بعد عدة أيام. تجنب المبيدات واسعة الأثر؛ لا تستخدم منتجًا إلا بعد تشخيص محلي والتحقق من تسجيله والملصق وفترة الأمان."
