    "summaryAr": "تفضل هذه المجموعة غالبًا الشمس والصرف، وتزهر أفضل مع تجنب الإفراط في الري والتسميد. تحتاج الشتلات الجديدة ريًا منتظمًا حتى التجذير، ثم تتحمل فترات جفاف أقصر أو أطول بحسب النوع والتربة. استخدم دعامة للجهنمية وأبعد أشواكها عن الممرات.",
    "titleAr": "الشجيرات والكروم المزهرة المتحملة نسبيًا للجفاف",
