    "waterSeedlingAr": "بعد الغرس اسقِ بعمق، وافحص التربة يوميًا أول أسبوعين ثم أسبوعيًا خلال السنة الأولى؛ اسقِ عندما تجف عند 5–8 سم. لا تترك كرة الجذر تجف تمامًا وهي حديثة، لكن لا تغرقها. الرمل والحر والرياح تزيد التواتر، والطين والمطر يقللانه.",
    "waterYoungAr": "بعمر 1–3 سنوات افحص أسبوعيًا خلال الحر؛ اسقِ عميقًا عند جفاف منطقة الجذر بدل ريات سطحية متكررة. بعد التجذير خفف الري تدريجيًا مع مراقبة الذبول الحقيقي، فالماء الزائد قد يقلل الإزهار أو يسبب تعفنًا. الأصص تجف أسرع من الأرض."
