    "summaryAr": "تحتاج المتسلقات دعمًا ومساحة وتقليمًا دوريًا؛ تختلف احتياجاتها بين الياسمين النجمي المقاوم نسبيًا للجفاف واللبلاب الذي قد ينتشر بقوة. راقب النباتات الزاحفة حتى لا تغطي الشجيرات أو الأشجار أو المباني، ولا تترك القصاصات القابلة للتجذر على الأرض.",
    "titleAr": "المتسلقات والغطاءات الأرضية الزاحفة",
    "waterMatureAr": "بعد التأسيس اسقِ أثناء الجفاف الطويل عند جفاف التربة في منطقة الجذر؛ اللبلاب الراسخ قد يحتاج دعمًا أقل، والمتسلقات قرب المباني أو الأصص تجف أسرع. افحص العمق لا السطح فقط، وزد الري في الرمل والحر والرياح، وقلله في الظل والطين وبعد المطر.",
    "waterSeedlingAr": "بعد الغرس اسقِ كرة الجذور جيدًا، وافحص يوميًا أول أسبوعين ثم أسبوعيًا في السنة الأولى عند عمق 5–8 سم؛ اسقِ إذا جفت. لا تغرق الجذور. النباتات على جدار أو تحت سقف لا يصلها مطر، والأصص والحر والرياح تجفف أسرع؛ الظل والتربة الثقيلة يقللان الري.",
    "waterYoungAr": "بعمر 1–3 سنوات افحص أسبوعيًا خلال الحر، واسقِ بعمق عند جفاف التربة قرب الجذور. قلل الري عند استقرار الياسمين النجمي واللبلاب في أرض مناسبة، لكن راقب المتسلقات على الجدران والأصص التي لا يصلها المطر. لا تكرر الرش على الأوراق ليلًا."
