        "treatmentAr": "أزل الأوراق شديدة الإصابة، وجفف سطح الأوراق وحسّن دوران الهواء. لا تستخدم مبيدًا قبل تحديد سبب البقع؛ عند استمرارها خذ عينة إلى جهة إرشاد نباتي محلية."
