        "signsAr": "تنقيط باهت دقيق أو برونزة على الأوراق، وأحيانًا خيوط رفيعة أسفلها.",
        "treatmentAr": "اعزل النبات واشطف السطحين السفلي والعلوي بلطف وكرر الفحص والغسل. عند استمرار الإصابة استخدم صابونًا حشريًا مسجلًا للنباتات الداخلية بعد اختبار ورقة واتباع الملصق."
