    "plantingSeasonAr": "أفضل وقت للنقل أو تبديل الأصيص الربيع عند بدء النمو، ويمكن في أوائل الخريف إذا كان الجو معتدلًا. تجنب النقل في موجة حر أو وقت الإزهار الكامل. تختلف حاجة السكون والبرودة بحسب الصنف؛ لا يُفترض أن يزهر صنف غير ملائم لشتاء المدينة.",
