        "signsAr": "كتل بيضاء قطنية عند قواعد الأوراق أو الجذور، مع ضعف النمو أو إفراز لزج.",
        "treatmentAr": "اعزل النبات وامسح الآفات المرئية بقطنة مبللة بالماء أو أزلها يدويًا؛ يمكن شطف النبات. كرر الفحص أسبوعيًا. إذا استمرت الإصابة فاستعمل صابونًا حشريًا مسجلًا بعد اختبار جزء صغير واتباع الملصق."
