    "plantingSeasonAr": "للزراعة أو النقل في أصيص الأفضل الربيع، ويمكن أوائل الخريف في منطقة معتدلة. تجنب التربة المتجمدة أو المغمورة والحر والجفاف الشديد. ارفع حجم الوعاء تدريجيًا عند امتلائه بالجذور.",
