    "summaryAr": "شجيرة دائمة الخضرة تتحمل الظل والجو المعتدل، لكن أصيصها يحتاج صرفًا جيدًا وريًا عند الحاجة. الأوراق المبرقشة قد تحترق تحت شمس حارة مباشرة.",
    "titleAr": "غبار الذهب (الأوكوبا) في الظل",
    "waterMatureAr": "النبات المتأصل في حوض خارجي قد يحتاج ماءً قليلًا بعد الاستقرار إلا في الحر والجفاف؛ أما النبتة البالغة في أصيص فتظل محدودة الجذور: اختبر أول 3 سم واسقِ إذا جفت، ثم أفرغ الصحن. تجنب التربة المشبعة والجفاف الطويل في الحر.",
    "waterSeedlingAr": "في السنة الأولى، افحص رطوبة الوسط كل يومين أو ثلاثة أيام في الدفء؛ اسقِ عندما يجف أول 2–3 سم، مع بقاء العمق رطبًا قليلًا. في الحر والرياح افحص بوتيرة أعلى، وفي الشتاء أو الظل قلل الري. صفِّ الفائض من الصحن.",
