    "plantingSeasonAr": "إعادة الزراعة في الربيع أو بداية الصيف عند بدء النمو، لا في موجة الحر. يمكن الإكثار بالعقل في الجو الدافئ؛ في حالة Dracaena sanderiana يمكن نموه في الماء أو التربة، لكنه ليس خيزرانًا حقيقيًا.",
