    "summaryAr": "أوراق استوائية للبيت الدافئ، تتفاوت بين نباتات تتحمل جفافًا معتدلًا وأخرى مثل الكروتون تحتاج رطوبة أكثر. يبدأ نجاحها بضوء ملائم وتصريف جيد واختبار التربة، لا بجدول أسبوعي ثابت.",
    "titleAr": "نباتات أوراق استوائية داخلية، مع استثناء خاص للبامبو الحظي",
    "waterMatureAr": "للنباتات البالغة في التربة اختبر الإصبع/عودًا خشبيًا قبل الري؛ الكروتون لا يترك ليجف طويلًا، بينما الدراسينا والبشيرة قد تتحملان جفافًا سطحيًا أكثر، والبوثوس والمونستيرا متوسطان. اسقِ حتى يخرج قليل من الفائض ثم أفرغ الصحن. يزيد الري مع الضوء القوي والحر والجفاف والوعاء الضيق، ويقل بالشتاء والظل والبرودة. للبامبو المائي غطِّ الجذور وبدّل الماء أسبوعيًا؛ الماء الراكد أو نقصه يسبب مشكلات.",
    "waterSeedlingAr": "في السنة الأولى للأصص الترابية افحص أول 2–3 سم كل يومين إلى أربعة في الدفء، واسقِ عندما تجف التربة السطحية وفق النوع، ثم دع الفائض يخرج. للكروتون ابدأ عند جفاف نحو 1–2 سم؛ للبوثوس والبشيرة والمونستيرا اترك السطح يجف قليلًا؛ للدراسينا اترك الوسط يجف باعتدال. للبامبو المائي أبقِ الجذور مغمورة وبدّل الماء أسبوعيًا، ولا تستخدم اختبار تربة.",
    "waterYoungAr": "بعمر 1–3 سنوات افحص أسبوعيًا على الأقل وكل بضعة أيام في الحر. لا تسقِ حتى تلمس جفاف السطح المطلوب للنوع: نحو 1–2 سم للكروتون، وجفاف سطحي معتدل للبوثوس والبشيرة والمونستيرا، وجفاف أكبر قليلًا للدراسينا. اترك ماء الصرف يخرج. للبامبو في الماء غيّر الماء أسبوعيًا؛ في التربة اسقِ عند جفاف أول 2–3 سم."
