    "matchNotesAr": "يشمل Spathiphyllum spp. (زنبق السلام)، Dieffenbachia spp. (دفنباخيا)، Anthurium spp. (أنثوريوم). جُمعت لاحتياجاتها العامة من دفء وضوء منتشر وتربة رطبة باعتدال؛ دفنباخيا لا تحتاج أن تبقى مغمورة، والأنثوريوم يحتاج وسطًا هوائيًا.",
