    "waterMatureAr": "للنباتات البالغة افحص عمقًا 2–3 سم بإصبعك: زنبق السلام يميل إلى وسط رطب بالتساوي، بينما بقية المجموعة تتحمل جفافًا سطحيًا بسيطًا قبل الري. اسقِ بغزارة مناسبة حتى يخرج الفائض ثم أفرغه. يزيد الاستهلاك مع الحرارة والضوء وحجم النبات، ويقل في الشتاء والظل؛ تجنب الغمر المزمن.",
