    "waterYoungAr": "بعمر 1–3 سنوات افحص الوسط مرتين أسبوعيًا في الجو الدافئ. اسقِ زنبق السلام عندما يبدأ السطح بالجفاف دون انتظار ذبول متكرر؛ والدفنباخيا/الأنثوريوم عندما يجف أول 2–3 سم مع بقاء الداخل رطبًا قليلًا. لا تترك ماء راكدًا؛ قلل الري في الشتاء."
