    "lightSoilAr": "النوع هو الذي يحدد ضوءًا خارجيًا أو داخليًا؛ كثير من أشجار البونساي المعتدلة تحتاج موسمًا في الخارج ولا تصلح غرفة دافئة طوال السنة. استخدم وسط بونساي خشنًا نافذًا يناسب النوع ووعاءً بفتحات تصريف، لا تربة حديقة ثقيلة.",
    "matchNotesAr": "الكتالوج يذكر «Various species (Bonsai form)» ولا يحدد الاسم العلمي؛ لذا لا يمكن مطابقة احتياج نوع بعينه. هذا إطار عام للحاوية الضحلة فقط، ويلزم معرفة النوع (داخلي استوائي أم شجرة خارجية معتدلة) قبل تقرير الضوء والشتاء والري النهائي.",
