    "plantingSeasonAr": "التقليم الجذري وإعادة الزراعة عادة في موسم السكون أو بداية النمو المناسب للنوع، لا وفق موعد موحد. لا تنقل الشجرة من وعاء ضحل أو تقلم جذورها دون معرفة النوع وحالته؛ تجنب الحر الشديد والصقيع أثناء العمل.",
