    "plantingSeasonAr": "الأفضل الغرس في الربيع بعد انحسار البرد، أو في الخريف المعتدل حيث لا يواجه النبات صقيعًا قريبًا؛ تجنب نقل الشتلة وقت الحر الشديد أو الرياح الجافة. ازرع المطعوم بحيث تبقى منطقة التطعيم فوق سطح التربة، ولا تدفن الجذع.",
