    "summaryAr": "رعاية عامة للحمضيات المحبة للدفء، مع ضبط الري حسب حجم الشجرة والطقس ونفاذية التربة. الأصناف والجذور قد تختلف في احتمال البرد والملوحة؛ لا يعني إدراجها أن كل صنف مناسب لكل موقع.",
    "titleAr": "الحمضيات: الليمون والبرتقال واليوسفي وما شابهها",
    "waterMatureAr": "للشجرة البالغة وسّع البلل من قرب الجذع إلى ما بعد حافة المجموع الخضري، واسمح بجفاف نحو 15 سم من سطح التربة قبل الري التالي؛ هذا دليل استرشادي لا موعد ثابت. احتياج الماء يتغير مع قطر التاج والنوع والموسم والتربة، لذا افحص رطوبة الجذور، وراقب الحرارة، المطر، الملوحة ونظام التنقيط. الرمل والحر يسرّعان الجفاف؛ الطين والبرد والمطر يقللانه. تجنب الري الضحل المتكرر والتشبع الطويل.",
    "waterSeedlingAr": "في السنة الأولى افحص كرة الجذور والتربة تحتها بإصبع أو مجرفة صغيرة؛ اسقِ ببطء عندما تبدأ منطقة الجذور بالجفاف، حتى تبتل بعمق دون غمر أو جريان. في الأصيص افحص أول 5 سم تقريبًا، واسقِ حتى يخرج قليل من الماء من فتحات التصريف ثم أفرغ الصحن. افحص بوتيرة أعلى في الحر والريح الجافة؛ خفف بعد المطر والبرد. التربة الرملية والأصص الصغيرة تجف أسرع من الطينية.",
    "waterYoungAr": "لعمر 1–3 سنوات بلّل مساحة الجذور لا الجذع وحده. افحص التربة على عمق نحو 10–15 سم؛ إذا جفت، اسقِ ريًا عميقًا ثم اترك التربة تجف جزئيًا قبل التكرار. في موجات الحر أو التربة الرملية قصّر الفاصل، وفي الطين والجو البارد أو بعد المطر طوّله. لا تعتمد جدول أيام ثابتًا ولا ريات سطحية يومية؛ الجفاف قد يظهر بانطواء الورقة وتبلد لونها."
