        "preventionAr": "اجمع الثمار الناضجة والساقطة يوميًا، وأزل الفاكهة المصابة، ويمكن تغطية الثمار بشبك ناعم قبل النضج مع تثبيته جيدًا.",
        "signsAr": "ثقوب دقيقة أو ليونة وتعفن داخل الثمرة، وقد تسقط الثمار قبل الحصاد.",
        "treatmentAr": "أتلف الثمار المصابة ولا تتركها تحت الشجرة، وراقب المصائد عند توفر إرشاد محلي. لا تستخدم منتجًا كيميائيًا إلا إذا كان مسجلًا محليًا للتين والآفة مع ملصق وفترة أمان مناسبة."
