        "signsAr": "بقع طرية أو رائحة تخمر وعفن رمادي/داكن على الثمرة أو حول فتحة العين في التين.",
        "treatmentAr": "أزل الثمار المصابة فورًا وحسّن التهوية، وتجنب ملامسة الثمار للتربة. لا تعالج بالرش إلا بعد تشخيص دقيق ووفق منتج مسجل وفترة أمان."
