    "plantingSeasonAr": "اغرس الشتلات في الربيع المعتدل، أو في الخريف إذا بقي وقت لتكوين الجذور قبل البرد؛ تجنب أيام الحر والجفاف. اختر موقعًا مشمسًا دافئًا، واترك مساحة واسعة للتاج والجذور. يمكن تقييد جذر التين عند الرغبة في ضبط حجمه، لكن ذلك يجعل مراقبة رطوبته أكثر أهمية.",
