    "summaryAr": "التين والتوت الشجري أشجار دافئة تتحمل الجفاف بعد التأسيس بدرجات مختلفة، لكن الإثمار الجيد يحتاج ماءً منتظمًا أثناء النمو. التين المقيد الجذور أو المزروع في أصيص يجف أسرع، ويثمر التين بصورة أفضل في موقع دافئ مشمس.",
    "titleAr": "التين والتوت الشجري",
    "waterMatureAr": "الشجرة البالغة المتجذرة أعمق يمكن أن تتحمل فترة جفاف أكثر من الشتلة، لكن المحصول الأفضل يحتاج رطوبة منتظمة خلال موسم النمو. افحص تحت المهاد وداخل منطقة الجذور؛ اسقِ ببطء عند جفافها واتركها تصرّف الماء. الجدار المشمس والأصيص وحر الصيف يسرعون الجفاف؛ التربة الثقيلة والمطر يبطئانه. تجنب ماءً راكدًا حول الجذور.",
    "waterSeedlingAr": "في السنة الأولى افحص التربة قرب الجذور بإصبع أو مجرفة صغيرة؛ اسقِ عندما يبدأ عمق 5–10 سم بالجفاف حتى يبتل محيط الجذور ولا يركد الماء. راقب يوميًا في الحر إذا كان التين في أصيص أو قرب جدار يحجب المطر. الرمل والريح والحر يزيدون الحاجة؛ الطين والمطر يخفضانها.",
    "waterYoungAr": "بعمر 1–3 سنوات افحص رطوبة التربة على عمق 10–15 سم، واسقِ بعمق عند جفافها، خصوصًا في أثناء نمو الأوراق والثمار. التين المقيد الجذور أو بالأصيص يحتاج فحصًا أكثر تكرارًا من شجرة مفتوحة الجذور؛ تجنب التذبذب الشديد بين الجفاف والغمر، وخفف الري بعد المطر وفي البرد."
