        "signsAr": "ثقوب أو ليونة وتعفن في الثمار وقد توجد يرقات داخلها؛ قد يتضرر المحصول قبل ظهور علامات واضحة على الورق.",
        "treatmentAr": "أزل الثمار المصابة وأتلفها، وراقب المصائد وفق الإرشاد المحلي. لا تستخدم مبيدًا إلا إذا كان مسجلًا محليًا للمحصول والآفة وفترة الأمان معروفة؛ التكيس والإصحاح أولوية."
