        "signsAr": "ثقوب صغيرة، ليونة أو تعفن مبكر وقد تظهر يرقات في الثمرة؛ تختلف أهميتها باختلاف النوع والمنطقة.",
        "treatmentAr": "أتلف الثمار المصابة، ونظف تحت الشجرة، واستخدم المصائد للرصد عند توصية الإرشاد المحلي. لا ترش دون تشخيص محلي وملصق يجيز الاستعمال على النوع وفترة ما قبل الحصاد."
