        "treatmentAr": "أزل الثمار المشققة والمتعفنة ولا تتركها على الشجرة أو الأرض؛ حسّن انتظام الري للموسم التالي. لا يعالج التشقق بمبيد لأنه غالبًا اضطراب مائي."
