    "summaryAr": "نباتات مجموعة متباينة لكنها عمومًا دافئة وتتحمل الجفاف بعد التأسيس بدرجات متفاوتة. لا تعني صفة التحمل إهمال الري: الشتلات تحتاج انتظامًا، والرمان يتأثر بجفاف ثم وفرة ماء مفاجئة بتشقق الثمار. تحقق من الغرض والصنف والهوية.",
    "titleAr": "أشجار دافئة متحملة نسبيًا للجفاف: السدر والعناب والخروب والرمان والسماق والجميز",
    "waterMatureAr": "بعد التأسيس، اسقِ بعمق أثناء الجفاف الطويل وعند نمو ثمار الرمان أو الجميز بحسب نوع الشجرة، ثم اترك التربة تجف جزئيًا. افحص أسفل سطح التربة قرب الجذور ولا تعتمد على جدول يومي. الأشجار الأكبر ذات التاج الواسع تحتاج بلل مساحة أكبر، وليس لترات ثابتة؛ الحر والرياح والرمل يزيدون الفقد، والطين والمطر يقللانه. الانتظام في الرمان يقلل تشقق الثمار؛ تجنب التشبع.",
    "waterSeedlingAr": "في السنة الأولى اسقِ مباشرة بعد الغرس، وافحص التربة داخل كرة الجذور يوميًا في الأسبوع الأول ثم بوتيرة أقل حسب الجفاف. اسقِ عندما تجف أول 5–10 سم من التربة، ببطء حتى تبتل الجذور دون بركة. الحر والريح والرمل ترفع الحاجة، والطين والمطر والبرد تخفضها؛ لا تعطي الشتلة جرعات سطحية صغيرة متكررة إذا كان يمكن ترطيب الجذور بعمق.",
    "waterYoungAr": "بعمر 1–3 سنوات افحص الرطوبة على عمق 10–15 سم واسقِ عند الجفاف، مع زيادة الانتباه أثناء موجات الحر ونمو الثمار. السدر والعناب والخروب أكثر تحملاً بعد التأسيس من الرمان؛ لا تساوِ بينها. الرمل والتربة الضحلة تسرع الجفاف، والطين والمطر يطيلان الفترة. في الرمان تجنب تعطيشًا طويلًا يتبعه ري غزير مفاجئ."
