        "treatmentAr": "نظف المخلفات وقلم الأجزاء المصابة في وقت جاف؛ لا تعالج بقعًا غير مشخصة. إذا تكرر الضرر خذ عينة لمرشد محلي؛ أي مبيد فطري يجب أن يكون مسجلًا للنوع والمرض مع مراعاة الملصق."
