    "summaryAr": "كرمة قوية ضحلة الجذور، تحتاج إلى تعريشة وتربة سريعة التصريف ورطوبة منتظمة دون إغراق. الصقيع والحر الجاف الشديد وضعف الصرف تحديات رئيسية.",
    "titleAr": "باشن فروت (فاكهة العاطفة) – Passiflora edulis",
    "waterMatureAr": "للكرمة البالغة افحص رطوبة التربة قرب الجذور الضحلة، واسقِ عند بدء جفافها مع تجنب البلل المستمر. يزيد الاحتياج في الحر والرياح وفترة الإثمار، ويقل في الشتاء أو بعد الأمطار. الذبول مع تربة رطبة قد يكون مرض جذور/ذبولًا لا نقص ماء؛ لا تعالجه بزيادة الري تلقائيًا.",
    "waterSeedlingAr": "في السنة الأولى، افحص التربة الضحلة حول الجذور قبل الري؛ اسقِ عندما يبدأ السطح بالجفاف ولا تترك كتلة الجذور تجف تمامًا، مع تصريف الماء الزائد. في الحر والرياح والتربة الرملية افحص بوتيرة أعلى، وخفف الري في الطقس البارد أو بعد المطر.",
    "waterYoungAr": "بعمر 1–3 سنوات اسقِ بانتظام بحسب جفاف الطبقة العليا من التربة، إذ إن الجذور سطحية. حافظ على رطوبة مستقرة أثناء النمو والإزهار والإثمار، لكن اترك السطح يجف قليلًا ولا تغمر منطقة التاج؛ التربة الثقيلة والأمطار تستدعي تقليل الري."
