    "summaryAr": "شجرة فاكهة محبة للحرارة والشمس، تتحمل أنواعًا متعددة من التربة بشرط الصرف الجيد. الشتلات الحديثة أكثر حساسية للبرد من الأشجار الراسخة، والأصناف تختلف كثيرًا في الحجم.",
    "titleAr": "المانجو – Mangifera indica",
    "waterMatureAr": "للشجرة البالغة، اسقِ خلال فترات الجفاف الطويلة بعد التحقق من جفاف جزء من منطقة الجذور، لا وفق جدول ثابت؛ قلل الري عندما تهطل الأمطار أو تبقى التربة رطبة. راقب التوازن بين الرطوبة والصرف، وتجنب الإفراط خاصة أثناء موسم الإزهار الرطب حيث تزيد بعض الأمراض.",
