    "waterYoungAr": "بعمر 1–3 سنوات اسقِ بعمق عند بدء جفاف التربة في منطقة الجذور بدل الري السطحي المتكرر. افحص التربة قبل كل ري؛ الحر والجفاف والرياح تزيد الحاجة، أما البرودة والظل والتربة الثقيلة والأمطار فتقللها. لا تترك الماء راكدًا حول الجذع."
