    "summaryAr": "إرشادات تحفظية لأشجار القشطة الدافئة جيدة الصرف، مع الإشارة إلى اختلافات النوع. الأنواع الاستوائية مثل A. squamosa تحتاج دفئًا أكبر من الشيريمويا، وبعض الأشجار تحتاج تلقيحًا يدويًا؛ الصقيع والتغدق والملوحة قد تكون محدِّدة.",
