    "plantingSeasonAr": "الأفضل النقل أو الغرس في الربيع المعتدل أو أوائل الخريف بعد انقضاء موجة الحر، مع تجنب أيام الصقيع والحر الشديد. بعد النقل اترك الجروح والجذور المقطوعة تجف وتلتئم، ثم ابدأ ريًا حذرًا وفق إرشاد المشتل؛ لا تروِ تربةً مشبعة.",
