    "matchNotesAr": "للأغاف الأمريكي Agave americana (id-1779358172348-gt162) تحديدًا. أوراقه حادة، وهو أكثر عرضة من بعض الأغاف الأصغر لسوسة أنف الأغاف وفق نشرة جامعة أريزونا؛ لا تزرعه قرب ممر ضيق.",
