    "plantingSeasonAr": "الأفضل زراعته أو نقله في الربيع المعتدل بعد زوال الصقيع أو في أوائل الخريف قبل البرد. تجنب الحر القاسي، ولا تسقِ مباشرةً في وسط مشبع. استخدم قفازات ونظارات عند النقل بسبب الأشواك الطرفية والحواف الحادة.",
