        "signsAr": "نقاط صفراء قد تتحول إلى بنية على الأوراق، وقد ترتبط البرودة والرطوبة العالية.",
        "treatmentAr": "اعزل النبات وأزل الأوراق المصابة بأداة نظيفة إن كان الضرر محدودًا، وخفف الرطوبة وحسّن التهوية. اطلب تشخيصًا محليًا إن انتشر؛ لا تستخدم مبيدًا بلا دليل ملائم وملصق مسجل."
