    "summaryAr": "عصاري ورقي قليل المتطلبات نسبيًا، يناسب أصيصًا جيد التصريف وإضاءة قوية. تجنب الصقيع وبلل الجذور المستمر، ولا تأكل النبات أو تستخدمه علاجًا.",
    "titleAr": "الألوة فيرا",
    "waterMatureAr": "للنبتة البالغة اسقِ بعمق بعد جفاف التربة تمامًا، ثم اتركها تصرف. اختبر بإدخال إصبع أو عود في الوسط، ولا تعتمد على جفاف السطح وحده. قلل الري في الشتاء والخمول والبرد؛ الحر والضوء القوي والرياح والأصيص الصغير تسرّع الجفاف، بينما الوسط الثقيل والرطوبة والظل تبطئه. الماء الراكد يسبب تعفن الجذور.",
    "waterSeedlingAr": "في السنة الأولى افحص الوسط قرب الجذور؛ اسقِ رية كاملة ثم اترك التربة تجف تمامًا قبل تكرار الري، مع عدم إبقاء الأصيص في الماء. الأصيص الصغير والحر والضوء القوي والهواء الجاف تزيد الجفاف؛ البرد وقلة الضوء والتربة الثقيلة والرطوبة تقلله. الشتلة لا تُروى تلقائيًا لمجرد صغرها.",
    "waterYoungAr": "بعمر 1–3 سنوات اسقِ جيدًا حتى يخرج الماء من الثقوب عند جفاف الوسط حتى العمق، ثم أفرغ الصحن. انتظر الجفاف الكامل قبل الرية التالية؛ خفف في الشتاء أو عند انخفاض الضوء. يزداد التكرار فقط إذا جفت الجذور أسرع في الحر أو الوعاء الصغير، لا وفق أيام ثابتة."
