    "summaryAr": "نبات أوراق منزلي؛ لا تعامله كصبار صحراوي رغم أن بعض أنواعه ذات أوراق لحمية. الضوء الساطع غير المباشر والري بعد جفاف الوسط وتصريف الماء أساس الرعاية.",
