    "matchNotesAr": "لـ«صباريات مشكلة» وSucculent (various genera) (id-1779615668839-03khj). الاسم يقول أجناسًا متنوعة ولا يحدد الأنواع؛ يُستعمل الملف للصبارات المعروفة فقط داخل الخليط، مع ضرورة فصل النباتات ذات احتياجات الماء أو الضوء المختلفة.",
