    "summaryAr": "الصبارات ليست نوعًا واحدًا، وهذا ملف أساس لا بديل عن بطاقة النوع. ابدأ بمزيج نافذ وضوء قوي وري بعد جفاف التربة، وافصل الصبار عن العصاريات الأعلى احتياجًا للماء إذا اختلف جفاف الوسط.",
    "titleAr": "مجموعة صبارات متنوعة غير محددة النوع",
    "waterMatureAr": "للصبار البالغ دع تربة الجذور تجف تمامًا بين الريات، ثم اسقِ حتى التصريف دون برك. افحص العمق ولا تساوِ بين أصناف المجموعة: النباتات الصغيرة والأصيص الفخاري والحر تجف أسرع، والأصيص الكبير والتربة الثقيلة والبرد والظل والرطوبة أبطأ. خفف الري خلال الخمول.",
    "waterSeedlingAr": "في السنة الأولى اختبر رطوبة الوسط قرب الجذور بعود أو إصبع، واسقِ عند الجفاف الواضح ثم دع الماء يخرج والوسط يجف بين الريات. راقب الشتلات أكثر لأن جذورها صغيرة، لكن لا تفرط. الحر والهواء والشمس والأصيص الصغير تزيد الجفاف؛ البرد والظل والطين والرطوبة تقلله. النوع الدقيق قد يغير ذلك.",
    "waterYoungAr": "بعمر 1–3 سنوات اسقِ جيدًا حول الجذور عندما يجف الوسط إلى عمقه، ثم أفرغ الصحن. اختبر كل أصيص على حدة؛ لا تروِ المجموعة في وقت واحد بلا فحص. زِد الانتباه في الحر والنمو النشط والخارج، وخفف مع البرد والمطر والظل أو التربة التي تبقى رطبة."
