        "preventionAr": "اترك مسافة وهواءً بين النباتات، واسقِ عند قاعدة النبات، واجمع الأوراق المصابة والمتساقطة ولا تتركها تحت الشجيرة.",
        "signsAr": "بقع أرجوانية أو سوداء غير منتظمة على الأوراق، اصفرار وتساقط مبكر، وقد تظهر آفات داكنة على الأفرع.",
        "treatmentAr": "أزل الأوراق والأفرع المصابة وتخلّص منها، ونظّف الأدوات وحسّن التهوية والري الأرضي. راقب النمو الجديد. لا تستخدم مبيدًا تلقائيًا؛ إن لزم منتج، تحقّق من تسجيله محليًا للورد واتبع الملصق وفترة إعادة الدخول وحماية الملقحات."
