        "treatmentAr": "قصّ الأجزاء المصابة وتخلّص منها، حسّن دوران الهواء وتابع انتشار العلامات. تجنب الخلطات المنزلية غير المختبرة؛ استشر مشتلًا أو إرشادًا محليًا قبل أي منتج، مع الالتزام بملصقه المحلي."
