    "summaryAr": "نبات قصير محب للشمس والتربة جيدة الصرف، مناسب للأحواض الجافة نسبيًا بعد تأسيسه، لكنه يحتاج رطوبة منتظمة عند الزراعة.",
    "titleAr": "الغازانيا: زهرة الشمس والجفاف",
    "waterMatureAr": "النبات الراسخ يحتاج ريًا تكميليًا عند استمرار الجفاف أو الذبول مع جفاف التربة؛ غالبًا يقل احتياجه عن الحوليات الأخرى. افحص التربة أولًا، فالكمية والفاصل يتغيران بحسب عمق التربة وحجم النبات والصرف والحرارة، ولا يلزم الري إذا بقيت التربة رطبة.",
    "waterSeedlingAr": "في السنة الأولى، تحقّق يوميًا أو كل بضعة أيام من رطوبة كرة الجذر بإصبعك عند عمق 3–5 سم، خاصة في الأصيص والحر والرياح. اسقِ عندما يبدأ هذا العمق بالجفاف حتى تبتل منطقة الجذور، ثم اترك الماء الزائد يصرّف. التربة الرملية والحر تسرع الجفاف؛ الطين والمطر والجو البارد تقلل الحاجة.",
    "waterYoungAr": "بعد التجذّر وحتى عمر 1–3 سنوات، افحص عمق 5–8 سم واسقِ عند الجفاف الواضح، بعمق لا برشات متكررة. زد الفحص في موجات الحر والأصص، وقلله في الطقس المعتدل أو بعد المطر؛ لا تترك الجذور في تربة مبتلة باستمرار."
