    "matchNotesAr": "ينطبق على قدسية (Tagetes erecta)، عرف الديك (Celosia argentea)، وفينكا (Catharanthus roseus). هذه حوليات موسمية في الحدائق، وإن كانت الفينكا والقطيفة والسلوزيا تتحمل الجفاف النسبي بعد الاستقرار؛ الشتلات تحتاج ريًا منتظمًا.",
