        "signsAr": "مناطق بنية ميتة على الأزهار أو الأوراق وقد يغطيها زغب رمادي في جو رطب.",
        "treatmentAr": "اقطع الأجزاء المصابة وتخلص منها ونظف الأدوات، ثم حسّن التهوية والصرف. إذا تكرر المرض فتأكد من النوع والتشخيص محليًا قبل أي علاج؛ لا تستخدم مبيدًا إلا بملصق يصرح بالنبات والآفة."
