        "signsAr": "مستعمرات على النمو الطري، التفاف أوراق أو إفراز لزج.",
        "treatmentAr": "اغسل الحشرات بتيار ماء لطيف أو أزلها يدويًا ثم أعد الفحص. لا تستخدم مبيدًا واسع الأثر كإجراء وقائي؛ إن لزم منتج، تحقّق من تسجيله محليًا والتزم بالملصق وفترة إعادة الدخول."
