    "matchNotesAr": "مطابقة الاسم العلمي: Mentha spp، Mentha longifolia، وMentha pulegium (النعناع البري/الفليو). قد تختلف الأنواع في تحمل الجفاف والحر، لكن جميعها تنتشر بالجذامير؛ احتواؤها في أصيص يقلل اجتياحها للحوض.",
