    "summaryAr": "أعشاب معمرة محبة لتربة رطبة باعتدال مع تصريف جيد؛ لا تتركها جافة طويلًا ولا مشبعة بالماء. النعناع الفليو نوع مختلف عن النعناع المزروع العام، وهذا الدليل إرشاد بستني لا يقدم استخدامًا غذائيًا أو طبيًا.",
