    "plantingSeasonAr": "ازرع البذور أو الشتلات في الربيع بعد زوال خطر الصقيع ودفء التربة والليالي؛ في المناطق الحارة جدًا يفضل الخريف المعتدل أو أواخر الشتاء. لا تنقله في ليلة باردة أو قبل موجة حر شديدة.",
