    "summaryAr": "ينمو الريحان في موسم دافئ بتربة خصبة نسبيًا ورطبة باعتدال دون تغريق. عند الحر الشديد تفيده ظلال بعد الظهر والري عند جفاف التربة، ويعاد زرعه سنويًا غالبًا.",
    "titleAr": "الريحان: عشب موسمي محب للدفء",
    "waterMatureAr": "اسقِ النبات المكتمل النمو بعمق عند جفاف أول 3–5 سم من التربة؛ لا تعتمد عدد أيام ثابتًا. في الحر والريح والأصيص افحص كثيرًا، وقد يحتاج ريًا أكثر؛ في الجو البارد أو المطر أو التربة الثقيلة أبطئ الري. لا تدع الماء راكدًا حول الجذور.",
    "waterSeedlingAr": "في مرحلة الشتلة والسنة الأولى أبقِ منطقة الجذر رطبة باعتدال؛ افحص 2–3 سم من السطح، واسقِ حين تجف دون إغراق أو ترك الشتلة تذبل. الأصيص الصغير والحر والريح والشمس تزيد سرعة الجفاف؛ التربة الطينية والظل والمطر تقللها.",
    "waterYoungAr": "الريحان لا يعيش عادة 1–3 سنوات كنبتة واحدة في الحديقة، لذا ازرع شتلات جديدة كل موسم. إن بقيت نبتة في مكان دافئ خالٍ من الصقيع، افحص 3–5 سم واسقِ حين يبدأ العمق بالجفاف، محافظًا على رطوبة متوازنة غير مشبعة."
