        "treatmentAr": "اغسل أسفل الأوراق بالماء وكرر الفحص، واقص الأوراق المزدحمة. لا تستخدم صابونًا أو زيتًا إلا إن كان المنتج مسجلًا محليًا للعطرة؛ اختبر ورقة والتزم بالملصق وتجنب الرش في الحر."
