        "treatmentAr": "اعزل النبات واغسل أسفل الأوراق بتيار ماء؛ حافظ على الأعداء الحيوية. إذا استمرت الإصابة فاختر منتجًا مسجلًا محليًا واتبع الملصق بدقة."
