    "plantingSeasonAr": "ازرع الشتلات في الربيع بعد زوال الصقيع ودفء التربة، أو في الخريف المعتدل في المناطق الحارة. يمكن أخذ عقل من نمو غير مزهر في أواخر الصيف، لكن الشتلات الصغيرة لا توضع خارجًا عند برد أو قيظ شديد.",
