        "signsAr": "حواف أوراق سميكة ملتفة للأسفل وشاحبة أو صفراء، ثم تجف إلى بني؛ قد توجد حوريات رمادية بيضاء أسفل الورقة.",
        "treatmentAr": "تحمل الإصابة غالبًا. أزل الأوراق المشوهة فقط إذا كانت قليلة؛ لا تفرط في التقليم لأن ذلك قد يضر أكثر. لا حاجة لمكافحة كيميائية روتينية."
