        "signsAr": "بقع أو اصفرار وتساقط، خاصة في الأصص أو عقب بقاء الوسط مغمورًا؛ قد يكون السبب تربة قديمة سيئة الصرف أو بردًا.",
        "treatmentAr": "قلل الري، وجدد وسط الأصيص المتدهور في الربيع، وأزل الأوراق المتساقطة. إذا استمر الضرر اطلب تشخيصًا؛ لا تفترض أن كل بقعة مرض فطري."
