    "plantingSeasonAr": "ازرع الشتلات في الربيع المعتدل أو الخريف بعد انحسار الحر مع وقت لتثبيت الجذور. في المواقع الباردة تجنب الغرس قبيل الشتاء، وفي المواقع شديدة الحرارة لا تنقل شتلة صغيرة خلال القيظ.",
