        "signsAr": "حشرات لينة متجمعة على القمم وأسفل الأوراق، تجعد أو مادة لزجة وقد يظهر السواد السطحي.",
        "treatmentAr": "اغسل الحشرات بالماء أو أزل القمم الأكثر إصابة، وكرر المراقبة. الصابون أو الزيت لا يستخدم إلا بمنتج مسجل محليًا للمورينجا ووفق الملصق وفترة الحصاد."
