        "treatmentAr": "اغسل النموات بتيار ماء أو أزل الأوراق المتضررة، وراقب من جديد. يمكن الحفاظ على الأعداء الحيوية؛ أي منتج مكافحة يجب أن يذكر المورينجا على ملصقه المحلي صراحةً."
