    "plantingSeasonAr": "ازرع البذور أو الشتلات في الربيع الدافئ بعد زوال الصقيع، أو عند بداية موسم المطر المحلي إذا كان الصرف جيدًا. لا تغرس قبل موجة برد ولا تنقل شتلة صغيرة في أشد الحر.",
