    "summaryAr": "شجرة سريعة النمو في الدفء والشمس، تتحمل الجفاف بعد تكوين جذرها لكنها تتأثر بالصقيع. تحتاج ري تأسيسيًا منتظمًا ووسطًا غير مشبع، ويمكن تقليم القمم وهي صغيرة لتشجيع التفريع وتقليل الارتفاع.",
