    "waterMatureAr": "الشجرة البالغة في الأرض تتحمل الجفاف نسبيًا، لكن إنتاج الأوراق والنمو يقلان عند العطش؛ اسقِ عند جفاف التربة على عمق 8–10 سم وفي فترات الجفاف الممتد. الأصيص والحر الشديد يزيدان الفحص والري، بينما المطر والطين والنشارة تخفضه. تجنب إغراق منطقة الجذع.",
    "waterSeedlingAr": "في السنة الأولى حافظ على رطوبة كتلة الجذر دون تشبع، خصوصًا أول أشهر التجذير. افحص 3–5 سم؛ اسقِ عندما تجف، ثم دع الماء يتصرف. تزيد الحاجة في الحر والريح والتربة الرملية، وتقل مع المطر والتربة العميقة أو النشارة.",
    "waterYoungAr": "لعمر 1–3 سنوات، وسّع منطقة الفحص مع نمو الجذور: افحص 5–8 سم حول محيط الجذور، واسقِ بعمق إذا جفت التربة. بعد الاستقرار تتحمل فترات جفاف وقد تفقد بعض أوراقها؛ لا تعوض ذلك بري يومي إذا بقي العمق رطبًا."
