    "matchNotesAr": "مطابقة مباشرة للاسم العلمي Salvadora persica. المرجع الزراعي الحكومي يصف تحمله للبيئات القاحلة والجفاف والملوحة، لكن ذلك لا يعني تحمل كل تربة أو مياه مالحة ولا يضمن النجاح في كل مدينة؛ أبقِ التربة جيدة الصرف.",
