        "signsAr": "قد تظهر انتفاخات على أجزاء من النبات؛ مرجع الزراعة للهند يذكر ملاحظة أورام على معظم الأجزاء باستثناء الجذور، ولا يعني ذلك تلقائيًا إصابة خطرة.",
