        "treatmentAr": "أوقف الري الزائد وحسّن الصرف، وأزل الأنسجة المتحللة إن كان ذلك ممكنًا. إذا استمر الذبول مع تربة رطبة اطلب تشخيصًا محليًا بدل استخدام مبيد عشوائي."
