    "plantingSeasonAr": "أفضل موعد محلي هو الربيع الدافئ بعد زوال البرد، أو بداية الأمطار حيث تكون موجودة ويكون الصرف جيدًا. البذر يتبع نضج البذور وموسمها المحلي؛ لا تزرع شتلة صغيرة في القيظ أو عند احتمال صقيع.",
