        "signsAr": "قد يظهر على الثمار ثقب أو نقرة بنية مع تلف داخلي أو سقوط الثمرة؛ الخطر يخص النبات الذي يحمل ثمارًا، لا مجرد وجوده كزينة بلا ثمار.",
        "treatmentAr": "ابدأ بالنظافة وجمع الثمار، ويمكن استخدام المصائد للرصد وخفض الأعداد مع معرفة أنها لا تضمن السيطرة وحدها. إذا كانت الثمار للأكل فاستشر الإرشاد الزراعي المحلي عن خيارات مسجلة؛ لا تستخدم مبيدًا إلا إذا أجاز الملصق الزيتون وطريقة الاستخدام، مع الالتزام بفترة ما قبل الحصاد."
